UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b136819-okbPuuFAefYX.png', birthday = NULL, blood_type = NULL, voice_actor = '古川慎', height = NULL, description = '韓国ハンター協会に所属するAランクのハンター。' WHERE character_id = 'CH013714';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b148789-HmGZf4RUzEFw.png', birthday = NULL, blood_type = NULL, voice_actor = '榎木淳弥', height = NULL, description = 'ミン・ビョングは引退したハンターであり、韓国で10人しかいないSランクの一人、そして唯一のSランクヒーラーであった。 彼は「ホワイトタイガー」ギルドマスターのペク・ヨンホと親しい友人だった。第4回済州島開拓レイドに参加し、済州島ゲートのボスを討伐する任務を負った韓国レイドチームのメンバーでもあった。' WHERE character_id = 'CH013715';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324332-3LSmru8LAsLp.png', birthday = NULL, blood_type = NULL, voice_actor = '小林直人', height = NULL, description = NULL WHERE character_id = 'CH013716';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b184538-4J5sRSFKNLGQ.png', birthday = NULL, blood_type = NULL, voice_actor = '青木瑠璃子', height = NULL, description = 'パク・ヒジン（박희진）は、レッドゲート内に閉じ込められた際、ソン・ジンオに助けられた「ホワイトタイガーギルド」のメンバーである。' WHERE character_id = 'CH013717';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306666-k7s0nluzaWod.png', birthday = NULL, blood_type = NULL, voice_actor = '間宮康弘', height = NULL, description = 'ファン・ドンスクはCランクのハンターであり、ファン・ドンスの兄である。' WHERE character_id = 'CH013718';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306678-S3BtMZx1jFd7.png', birthday = NULL, blood_type = NULL, voice_actor = '廣瀬武央', height = NULL, description = 'コ・ミョンファンは、「ホワイトタイガー」ギルドに所属する韓国のCランクハンターである。' WHERE character_id = 'CH013719';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b184530-prSQOxMJid47.png', birthday = NULL, blood_type = NULL, voice_actor = '咲野俊介', height = NULL, description = 'ユ・ミョンハン（유명한）はジンホの父親であり、ヨジン建設の社長である。' WHERE character_id = 'CH013720';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b145722-qSJ71S6vpeeM.png', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = 'イグリスは、ソン・ジンウォが最初に手に入れたシャドウの一人である。当初、彼はジンウォが「ジョブチェンジクエストダンジョン」でジョブクエストをこなしていた際、インスタントダンジョン内の空の玉座を守っていた。  2度の「シャドウ抽出」の試みが失敗に終わった後、ソン・ジンウォは、空の玉座を守るのではなく、自分を守るよう彼を説得し、ナイトグレードのシャドウとして獲得した。' WHERE character_id = 'CH013721';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b138789-AhE8m0LWjE7E.png', birthday = NULL, blood_type = NULL, voice_actor = '上田麗奈', height = NULL, description = 'ギルド：ハンターギルド　クラス：ソードファイター　所属：済州島レイドパーティー、ソン・チユルの道場（弟子）　チャ・ヘインはハンターギルドの副ギルドマスターである。彼女はSランクのハンターであり、韓国で9位のハンターである。 彼女は「マナの匂い」という独自の能力を持ち、ソン・ジンウォ以外のハンターの匂いを嫌っている。' WHERE character_id = 'CH013722';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323043-1cRLO5gO0JSY.png', birthday = NULL, blood_type = NULL, voice_actor = '寺島拓篤', height = NULL, description = '元韓国人Sランクハンター。' WHERE character_id = 'CH013723';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b138793-eijpaPPkcipD.png', birthday = NULL, blood_type = NULL, voice_actor = '富田美憂', height = NULL, description = 'ハン・ソンイは、ヨ・ジンホとソン・ジンオの寄せ集めパーティーを通じてお金を稼いだ後、学校を中退したEランクのハンターである。彼女はソン・ジンアと友人関係にある。彼女が初めて登場したのは、ジンアが病院でジンオを見舞った時だったが、その時はまだジンオのことを知らなかった。' WHERE character_id = 'CH013724';
