UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b210098-Smco3qIRv0GD.png', birthday = NULL, blood_type = NULL, voice_actor = '藍原ことみ', height = NULL, description = 'ジーナはAランクの魔術師であり、Aランクのゲートでのソン・キホンのパーティーのレイドメンバーの一人だった。彼女は長い金髪と深紅の瞳をしている。身長は平均的で、非常に魅力的な体型をしている。 ジーナは真面目な性格で、ハイオークの一匹を殺したのは自分なのかというソン・キホンの質問に答える様子からも、そのことがうかがえる。' WHERE character_id = 'CH013732';
