UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135657-S5oHYHHVJnGa.jpg', birthday = NULL, blood_type = NULL, voice_actor = '石川由依', height = NULL, description = 'エリーゼ・ド・クロランスは、韓国を代表する医学部で最年少の女性教授であるソン博士が、海上で不慮の死を遂げた後、転生した王女である。 名外科医としての医学的知識を身につけた彼女にとって、これは過去の人間関係を修復し、病む帝国を癒やすチャンスとなるのか、それとも運命は繰り返される運命にあるのか？' WHERE character_id = 'CH013753';
