UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327835-ojLZKG4aVtSJ.png', birthday = NULL, blood_type = NULL, voice_actor = '保住有哉', height = NULL, description = NULL WHERE character_id = 'CH013769';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b193867-QB0S8Sz23Qie.png', birthday = NULL, blood_type = NULL, voice_actor = '岡本信彦', height = NULL, description = 'ホビン・ヨのカメラマンであり、同級生でもある。ゲーム配信中の喧嘩の様子が公になる前は、パクゴのカメラマンを務めていた。' WHERE character_id = 'CH013770';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b193869-l1YoNFjOmrU7.png', birthday = NULL, blood_type = NULL, voice_actor = '丹羽哲士', height = NULL, description = 'ホ・ビンは貧しい家庭に育った少年で、学校ではいじめに遭っていた――しかし、ある幸運な出来事をきっかけに、彼はNewTubeで一躍有名になる。' WHERE character_id = 'CH013771';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b193868-Q2r8Xb3oKX6C.png', birthday = NULL, blood_type = NULL, voice_actor = 'ファイルーズあい', height = NULL, description = 'ホ・ビン・ヨの映像編集者。彼女はホ・ビンとジ・ヒョクより1歳年下だ。' WHERE character_id = 'CH013772';
