UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', birthday = '6月24日', blood_type = NULL, voice_actor = '村瀬歩', height = 160, description = NULL WHERE character_id = 'CH013913';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', birthday = NULL, blood_type = NULL, voice_actor = '増田俊樹', height = NULL, description = NULL WHERE character_id = 'CH013914';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b127278-0qCQciTkPOMS.jpg', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = '壬氏は、内宮の事務を司る宦官である。その美貌は后妃たちをも凌ぐほどで、男女を問わず人々を驚嘆させるとされている。彼は常に従者の高順を伴っており、猫猫の聡明さと活発な振る舞いに興味を抱いている。' WHERE character_id = 'CH013915';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b126824-MqsCncTO1qpv.png', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = '猫猫は歓楽街で薬師として働き、師であり父でもあるルーメンを手伝いながら、その地域の住民たちの世話をしている。特に、彼女が生まれ育った「ヴェルディグリス・ホール」という遊郭には、特別な配慮を払っている。  ある日、薬草を採集中に彼女は誘拐され、皇帝の側室たちとその侍女たちだけが暮らす皇宮の内廷で、下級使用人として売られてしまう。外に出ることを許されない中、彼女の独特な性格と技能が、次第に彼女を謎めいた出来事に巻き込んでいく。' WHERE character_id = 'CH013916';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141151-u6mLf1y5k7PJ.jpg', birthday = NULL, blood_type = NULL, voice_actor = '寺島拓篤', height = NULL, description = 'マジックサークルランク：ティア3（分析魔法）　デジール・ハーマンは、『転生者の魔法は特別であるべき』の主人公である。シャドウワールドの攻略に失敗し、過去へと戻った彼は、未来が繰り返されないよう、仲間たちを強化することを決意する。 ヘブリオン学園では、平民は嫌われ、ベータクラスに配属される一方、貴族はアルファクラスに指定されている。デジールは、この階級制度を憎み、現状を変えたいと願う平民の一人である。その結果、' WHERE character_id = 'CH013917';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141154-QJQ3ieyGBS1F.jpg', birthday = NULL, blood_type = NULL, voice_actor = '瀬戸麻沙美', height = NULL, description = 'サークルレベル：4（ソードメイジ）  アゼスト・ジェドガー・F・ローグパレスは、ヘブリオン帝国の現皇帝であるギルティアン・ジェドガー・F・ローグパレスの長男であり、したがってヘブリオン帝国の皇位継承者である。 当初、アゼストは冷淡な性格で、デシール・グループの親しい友人たち以外の人々にはあまり関心を示さない傾向があった。' WHERE character_id = 'CH013918';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141152-ZnFSz0sTI1fD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '鈴代紗弓', height = NULL, description = 'サークルティアレベル：3（風魔法使い）　デシール・アーマンが「影の迷宮」から戻った後、初めてロマンティカと出会った際、彼女は貴族という立場ゆえに優越感を抱いていたが、物語が進むにつれてデシール・アーマンと親しくなるにつれ、その優越感は徐々に薄れていく。' WHERE character_id = 'CH013919';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141153-okb1ScsIZB0u.jpg', birthday = NULL, blood_type = NULL, voice_actor = '藤原夏海', height = NULL, description = 'サークル・ティア・レベル：3（ソードメイジ）　プラムは、デシール・アーマンが率いる平民で構成されたアルファパーティの一員である。' WHERE character_id = 'CH013920';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b305393-ThX9KabEJDpo.png', birthday = NULL, blood_type = NULL, voice_actor = '坂泰斗', height = NULL, description = NULL WHERE character_id = 'CH013921';
