UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b305391-vO5F2BqZSbGe.png', birthday = NULL, blood_type = NULL, voice_actor = '佳穂成美', height = NULL, description = 'カナレの城下町で、身寄りのない孤児の少女。奴隷商人たちから逃げていたところを、アルスとリッツに助けられた。' WHERE character_id = 'CH013923';
