UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b215258-A0t3nigiFfsF.png', birthday = '2月1日', blood_type = 'AB', voice_actor = '子安武人', height = 198, description = 'イーソン・マジック・アカデミーの3年生で、オルカ寮の寮長を務めている。マーガレットは風変わりな性格だが、「力こそ正義」を固く信じている。タルタルソースに奇妙なほどの執着を見せている。' WHERE character_id = 'CH003815';
