UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b215259-ZpVchb8qQeT3.png', birthday = '6月6日', blood_type = 'A', voice_actor = '内山昂輝', height = 174, description = 'イーストン・マジック・アカデミーの1年生で、オルカ寮の寮生。なんとか金貨を4枚手に入れることに成功し、そのおかげで「神の予言者選抜試験」への参加を許可された。' WHERE character_id = 'CH003824';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202422-DNcyHSn8ICHp.jpg', birthday = '3月3日', blood_type = 'AB', voice_actor = '梶裕貴', height = NULL, description = 'レイン・エイムズは、イーストン・マジック・アカデミーの2年生であり、現「神の予言者たち」のソード・ケイン、アドラー寮の寮長、そしてフィン・エイムズの兄である。' WHERE character_id = 'CH003825';
