UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324535-R0yUavYY33dK.png', birthday = '8月9日', blood_type = 'A', voice_actor = '角田雄二郎', height = 184, description = 'イーストン・マジック・アカデミーの3年生。ラング寮に所属している。' WHERE character_id = 'CH003829';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b179810-E34imq24Z2Gw.jpg', birthday = '9月1日', blood_type = 'O', voice_actor = '宮崎遊', height = NULL, description = 'ユキの大学の先輩で、国際クラブのメンバー。ドイツ語、英語、日本語の3か国語を話せる。また、世界中を旅することや、子供たちと交流することも好きだ。将来は、各国や異文化について教える教師になりたいと考えている。' WHERE character_id = 'CH003830';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b179809-pxG89n30MGwl.jpg', birthday = '11月4日', blood_type = 'A', voice_actor = '諸星すみれ', height = NULL, description = 'イツオミを通じて外の世界について学びたいと願う、聴覚障害のある大学生。' WHERE character_id = 'CH003831';
