UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323162-Zwm0KrxsELwt.png', birthday = NULL, blood_type = NULL, voice_actor = '荒井洸貴', height = NULL, description = '彼はオシの友人の一人だ。' WHERE character_id = 'CH003834';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206490-zXi4Z96IDuW3.png', birthday = '7月20日', blood_type = 'O', voice_actor = '本渡楓', height = NULL, description = 'リンは、ユキの大学時代の友人だ。彼女は、ユキとイツオミの関係を心から応援している。また、イツオミのいとこであるキョウヤのことが好きだ。' WHERE character_id = 'CH003835';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323964-U32mFNVSu18z.png', birthday = NULL, blood_type = NULL, voice_actor = '髙橋ミナミ', height = NULL, description = NULL WHERE character_id = 'CH003836';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206489-6Ewj3mocooVc.png', birthday = '4月5日', blood_type = 'A', voice_actor = '大塚剛央', height = NULL, description = 'ユキの幼なじみで、彼女のために手話を学び、その腕前も非常に優れている。幼い頃からユキを知っており、彼女に想いを寄せているため、ユキとイツオミの関係について心配している。' WHERE character_id = 'CH003837';
