UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b246023-JY3YgmQALjHM.png', birthday = '2月1日', blood_type = NULL, voice_actor = '畠中祐', height = NULL, description = 'シンはイツオミの高校時代の同級生で、現在は美容師として働いている。普段はクールな性格だが、お酒を飲むと急に陽気な性格に変わる。よくエマとつるんでおり、彼女の恋愛相談役を務めている。' WHERE character_id = 'CH003840';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b282662-eMBZCTHgAIto.png', birthday = '12月27日', blood_type = NULL, voice_actor = '東山奈央', height = NULL, description = NULL WHERE character_id = 'CH003841';
