UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325586-fETlN9S0Qini.png', birthday = NULL, blood_type = NULL, voice_actor = '奈良徹', height = NULL, description = NULL WHERE character_id = 'CH003859';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325571-yfxZgvzYZQrn.png', birthday = NULL, blood_type = NULL, voice_actor = '悠木碧', height = NULL, description = NULL WHERE character_id = 'CH003860';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325579-ZtlCqI91j5rV.png', birthday = NULL, blood_type = NULL, voice_actor = '家中宏', height = NULL, description = NULL WHERE character_id = 'CH003861';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325572-f1cI0iqMZmFk.png', birthday = NULL, blood_type = NULL, voice_actor = '小松昌平', height = NULL, description = NULL WHERE character_id = 'CH003862';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325580-6WoS3g00xLK7.png', birthday = NULL, blood_type = NULL, voice_actor = '堀井茶渡', height = NULL, description = NULL WHERE character_id = 'CH003863';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327406-eN7Ect76AMV8.png', birthday = NULL, blood_type = NULL, voice_actor = '和多田美咲', height = NULL, description = NULL WHERE character_id = 'CH003864';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325573-5TMjz2SeQ4dg.png', birthday = NULL, blood_type = NULL, voice_actor = '藤井隼', height = NULL, description = NULL WHERE character_id = 'CH003865';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325581-LmkMGccNbdr0.png', birthday = NULL, blood_type = NULL, voice_actor = '羽多野渉', height = NULL, description = NULL WHERE character_id = 'CH003866';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327407-DLvmHnyN8bvS.png', birthday = NULL, blood_type = NULL, voice_actor = '千葉進歩', height = NULL, description = NULL WHERE character_id = 'CH003867';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b138138-Nz9jNIHBVeRC.png', birthday = NULL, blood_type = NULL, voice_actor = '佐倉綾音', height = NULL, description = '巴は、女神の世界に存在する「至高の竜」の一人である。現在は深澄真に仕えている。気さくな性格で、新しいことに挑戦したり、日本の江戸時代に関する興味深いことを学んだりするのが好きだ。 以前の、怠惰で何事にも無関心だった世界観とは一線を画している。時には、危険なほど真面目ではない面もある。真の行動によってどのような変化が生まれるかを見守ること、そしてとりわけ新しいことを学ぶことに大きな喜びを感じている。' WHERE character_id = 'CH003868';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b138139-RyExQ4tdSsLG.png', birthday = NULL, blood_type = NULL, voice_actor = '鬼頭明里', height = NULL, description = '彼女はかつて「災厄の黒蜘蛛」と呼ばれており、女神の世界において唯一無二の存在である。現在はマコトに仕えている。マコトへの忠誠心は一途で率直であり、その度合いは危険なレベルに達することもある。 マコトに危害を加えようとする者なら誰であれ、躊躇なく滅ぼしてしまう。' WHERE character_id = 'CH003869';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b247735-x7YhxlUh0Cnn.png', birthday = NULL, blood_type = NULL, voice_actor = '津田健次郎', height = NULL, description = '識はリッチであり、現在は深澄真に仕えている。その出自や本名は不明である。 容易に確認できるのは、彼が魔法の知識において卓越した研究者であったということだ。死の前に、リッチとして蘇ったのか、あるいは自らリッチへと変貌を遂げたのかは定かではない。その時期や場所は不明である。分かっているのは、彼が非常に長い間リッチであり続け、かなりの名声を博しているということだけである。' WHERE character_id = 'CH003870';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b138137-yBtJdBlRziS9.png', birthday = '4月1日', blood_type = NULL, voice_actor = '花江夏樹', height = NULL, description = '深澄真は、このシリーズの主人公である。彼は、女神の世界へと送り込まれた3人の「世界旅行者」のうちの1人である。  本来、彼の両親と女神との契約によれば、異世界へ送られるのは彼一人であるはずだったが、女神は自身の美の基準に合わず、真を見捨てて世界の果てにある「荒野」へと放り出し、その一方で密かに地球から他の二人を拉致し、彼らを「英雄」として女神の世界へ送り込んだ。 ツクヨミ、すなわち' WHERE character_id = 'CH003871';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329305-Ymyjee3lMhl7.jpg', birthday = NULL, blood_type = NULL, voice_actor = '松岡禎丞', height = NULL, description = NULL WHERE character_id = 'CH003872';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b221532-91XGYscgssEi.png', birthday = NULL, blood_type = NULL, voice_actor = '辻親八', height = NULL, description = 'ベレンは、<a href="https://anilist.co/character/138137/Makoto-Misumi">深澄真</a>が出会った年配のドワーフで、現在はアソラおよびクズノハ社の鍛冶師の一人である。' WHERE character_id = 'CH003873';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319904-fy3fz5w2VriB.jpg', birthday = NULL, blood_type = NULL, voice_actor = '花守ゆみり', height = NULL, description = 'シフ・レンブラントは、<a href="https://anilist.co/character/247459/Patrick-Rembrandt">パトリック</a>とリサ・レンブラントの長女であり、ルトスガード・アカデミーの生徒である。 彼女は、母親や妹と共に、致命的なレベル8の呪いに苦しめられていた。' WHERE character_id = 'CH003874';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319912-2MZhrQ9Tx3Ne.jpg', birthday = NULL, blood_type = NULL, voice_actor = '井澤詩織', height = NULL, description = 'エヴァは、滅びたカレネオン王国の生存者の一人である。彼女は現在、解放された王国の新政府の統治者として活動している。' WHERE character_id = 'CH003875';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319920-s38T6lyIUyXQ.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小坂井祐莉絵', height = NULL, description = 'アベリアは、ルトスガード・アカデミーで<a href="https://anilist.co/character/138137/Makoto-Misumi">深澄真</a>の教え子である。卒業後は、クズノハ社に就職する予定で、現在はスパイとしての訓練を受けている。' WHERE character_id = 'CH003876';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327889-JUQyfdVGc65T.png', birthday = NULL, blood_type = NULL, voice_actor = '塩見宗真', height = NULL, description = NULL WHERE character_id = 'CH003877';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b247458-DfnYOlAbLuQd.jpg', birthday = NULL, blood_type = NULL, voice_actor = '田中美海', height = NULL, description = 'エリスは、アクアと共にクズノハ社で働いているフォレスト・オーガです。' WHERE character_id = 'CH003878';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319905-IFqFVkHqO4KB.jpg', birthday = NULL, blood_type = NULL, voice_actor = '沢城千春', height = NULL, description = '彼はリミア王国の第一王子であり、現在は王子という身分を隠し、普通の騎士として振る舞いながら、<a href="https://anilist.co/character/195918/Hibiki--Otonashi">ヒビキ</a>のパーティーに加わっている。' WHERE character_id = 'CH003879';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319913-ZlLVszedMiii.jpg', birthday = NULL, blood_type = NULL, voice_actor = '笹本菜津枝', height = NULL, description = 'ユキナツ・カズサは、<a href="https://anilist.co/character/319911/Tomoki-Iwahashi">トモキ</a>のパーティのメンバーです。 彼女は「フォース・プレイヤー」であり、ゴーレムの創造と制御を専門とする錬金術師の一種です。また、女神から授かったアーティファクトを基に、武器や装備品の製作にも取り組んでいます。' WHERE character_id = 'CH003880';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b320024-efwBJyWLg0QH.jpg', birthday = NULL, blood_type = NULL, voice_actor = '月城亜美', height = NULL, description = 'モーラはドラゴンサモナーであり、現在は<a href="https://anilist.co/character/319911/Tomoki-Iwahashi">トモキ</a>のパーティの一員として活動している。' WHERE character_id = 'CH003881';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327890-VPkVys5Hyq1L.png', birthday = NULL, blood_type = NULL, voice_actor = '中島卓也', height = NULL, description = NULL WHERE character_id = 'CH003882';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b264577-xslxdKwUGbDC.png', birthday = NULL, blood_type = NULL, voice_actor = '斉藤壮馬', height = NULL, description = '「御剣」とも呼ばれるランサーは、色白の肌と金髪を持ち、ヒューマンと全く同じ外見をした少年のような姿をしている。' WHERE character_id = 'CH003883';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319906-rxBjrFe84NfI.jpg', birthday = NULL, blood_type = NULL, voice_actor = '広瀬ゆうき', height = NULL, description = '彼女は、滅びたカレネオン王国の生存者の一人である。' WHERE character_id = 'CH003884';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319914-20GobQlijgfA.jpg', birthday = NULL, blood_type = NULL, voice_actor = '橘龍丸', height = NULL, description = 'イズモ・イクサベは、<a href="https://anilist.co/character/138137/Makoto-Misumi">マコト</a>の教え子の一人です。' WHERE character_id = 'CH003885';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321239-9zdI15lDJWVm.jpg', birthday = NULL, blood_type = NULL, voice_actor = '楠大典', height = NULL, description = 'イオは魔将の一人で、魔軍の教官兼現場指揮官を務めている。' WHERE character_id = 'CH003886';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327891-uj07qAiIJ9Fl.png', birthday = NULL, blood_type = NULL, voice_actor = '虎島貴明', height = NULL, description = NULL WHERE character_id = 'CH003887';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b247461-Y1IDu2K5GWgc.jpg', birthday = NULL, blood_type = NULL, voice_actor = '佐藤正治', height = NULL, description = 'モリスはレンブラント家の執事である。また、パトリック・レンブラントの右腕であり、かつては冒険家でもあった。' WHERE character_id = 'CH003888';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319907-my2FhQFkwUDH.jpg', birthday = NULL, blood_type = NULL, voice_actor = '伊東健人', height = NULL, description = '彼はルトスガード・アカデミーの生徒であり、ホプリーズ・ホーズ家の次男であり、リミア王国の貴族である。' WHERE character_id = 'CH003889';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319915-JFCAixGq5Bqu.jpg', birthday = NULL, blood_type = NULL, voice_actor = '田村奈央', height = NULL, description = 'チヤ＝ハヅキは、ローレル・コモンウェルスの大祭司であり、<a href="https://anilist.co/character/195918/Hibiki--Otonashi">ヒビキ</a>のパーティのメンバーである。' WHERE character_id = 'CH003890';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321240-sc8TZtMbDogM.jpg', birthday = NULL, blood_type = NULL, voice_actor = '藤井ゆきよ', height = NULL, description = 'ロナは魔将の一人で、敵に関する情報、潜在的な脅威、そして魔軍の前進の好機を収集する役割を担っている。' WHERE character_id = 'CH003891';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327892-aVeJ87GSV4MR.png', birthday = NULL, blood_type = NULL, voice_actor = '長谷川育美', height = NULL, description = NULL WHERE character_id = 'CH003892';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b221533-7FtFJRZCB6gv.png', birthday = NULL, blood_type = NULL, voice_actor = '早見沙織', height = NULL, description = 'エマは、<a href="https://anilist.co/character/138137/Makoto-Misumi">深澄真</a>の秘書であり、アソラの監督を務めている。' WHERE character_id = 'CH003893';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b249256-31OVFxOOP732.png', birthday = NULL, blood_type = NULL, voice_actor = '沢城みゆき', height = NULL, description = '彼女は著名な冒険者であり、巴と澪が加入する前は、ギルドに登録されていた最強の冒険者だった。彼女はドラゴンスレイヤーであり、ドラゴンとしてのランサーを倒した功績によりSSSランクを授与され、その後「ドラゴンスレイヤー」の称号を授かった。' WHERE character_id = 'CH003894';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319908-WYGgNHm145gD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '中原麻衣', height = NULL, description = '彼女はグリトニア帝国の王女であり、<a href="https://anilist.co/character/319911/Tomoki-Iwahashi">岩橋智樹</a>のパーティの監督を務めている。' WHERE character_id = 'CH003895';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319916-dJZ9lIYIkfd8.jpg', birthday = NULL, blood_type = NULL, voice_actor = '山口智広', height = NULL, description = 'ダエナ・セブルスは、<a href="https://anilist.co/character/138137/Makoto-Misumi">マコト</a>のクラスに参加した最初の5人の生徒のうちの1人です。' WHERE character_id = 'CH003896';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b271886-JRYxTQQ2EDUb.png', birthday = NULL, blood_type = NULL, voice_actor = '佐倉綾音', height = NULL, description = 'コモエは、このシリーズに繰り返し登場するキャラクターである。彼女は、最初のオフショットが死亡した後、巴によって生み出された2番目のフラグメントである。前のオフショットと同様、彼女の役割は、異空間「アソラ」に関する情報の収集と監視を支援することである。  最初の分身が消滅した後、2番目の分身にはより多くの力と強さが与えられ、アソラでも屈指の強さを誇る存在となった。さらに、戦闘志向の住民たちの戦闘訓練を監督するという役割も担っている。' WHERE character_id = 'CH003897';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327893-fp444JCWBhFY.png', birthday = NULL, blood_type = NULL, voice_actor = '平山ゆりか', height = NULL, description = NULL WHERE character_id = 'CH003898';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b247460-d5CaKxN7dXoX.jpg', birthday = NULL, blood_type = NULL, voice_actor = 'Lynn', height = NULL, description = 'アクアは、エリスと共にクズノハ社で働いているフォレスト・オーガだ。' WHERE character_id = 'CH003899';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b195918-gM6mmP0pbdeN.png', birthday = NULL, blood_type = NULL, voice_actor = '加隈亜衣', height = NULL, description = '音無響は、このシリーズに繰り返し登場するキャラクターである。彼女は、女神によってその世界へ召喚された「英雄」の一人である。響は、政治的な役職に最も適した、極めて計算高く、社交的な柔軟性を持つと言われている。 英雄であり冒険者でもある彼女は、素早い近接戦闘に長けており、よりバランスの取れた戦士および戦闘指揮官となるべく、長距離技や戦略といった自身の弱点を改善しようと努めている。彼女は、生まれながらに与えられた立場を重視する傾向がある。' WHERE character_id = 'CH003900';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319909-P8fOEX32ECHy.jpg', birthday = NULL, blood_type = NULL, voice_actor = '稗田寧々', height = NULL, description = 'ユーノ・レンブラントは、<a href="https://anilist.co/character/247459/Patrick-Rembrandt">パトリック・レンブラント</a>とリサ・レンブラントの次女であり、ルトスガード・アカデミーの生徒である。彼女は母親や姉と共に、致命的なレベル8の呪いに冒されていた。' WHERE character_id = 'CH003901';
