UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319910-XYLzGkk2W7x5.jpg', birthday = NULL, blood_type = NULL, voice_actor = '渡部紗弓', height = NULL, description = '彼女は「ロイヤルガード」であり、王族の護衛を任された騎士に与えられる最高位の階級である。また、大竜サザナミ「グロン」からの「神の加護」を受けている。 彼女は<a href="https://anilist.co/character/319908/Lili-Front-Glitonia">リリ・フロント・グリトニア</a>の親友であり、専属護衛でもあり、現在は<a href="https://anilist.co/character/319911/Tomoki-Iwahashi">トモキ</a>のパーティの一員として活動している。' WHERE character_id = 'CH003907';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319918-bfjkfy1b103N.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小清水亜美', height = NULL, description = 'ナバール・ポーラーは、悪魔と戦うために<a href="https://anilist.co/character/195918/Hibiki--Otonashi">ヒビキ</a>のパーティーに加わった傭兵だった。' WHERE character_id = 'CH003908';
