UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b170329-nLoZpvOU26Md.png', birthday = '3月12日', blood_type = 'A', voice_actor = '広瀬裕也', height = 173, description = '種族：人間　職業：世話役　所属：反魔軍（第7部隊）　家族：和倉青羽（妹）　反魔軍第7部隊の世話役。 上ノ木高校の3年生として在学中だったが、マトー災害に巻き込まれた後、羽前京香に救出され、彼女の「奴隷」となったことで、彼女と共に戦う力を授かった。  男性であるため、桃を摂取しても特殊な力を得ることができないという理由から、悪魔軍団の正式なメンバーになることはできなかった。' WHERE character_id = 'CH003915';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b162524-r8daVAJ32H4j.png', birthday = '9月4日', blood_type = 'O', voice_actor = '鬼頭明里', height = 167, description = '種族：ヒューマン・ピーチ　能力：「永遠の鎖」、<i>「スレーブ」</i>　所属：アンチデーモン軍団（第7部隊長）　京香は、ピーチたちから力を授かった女性たちの精鋭集団であるアンチデーモン軍団の第7部隊長である。 彼女は和倉優希の救い主であり、彼を自分の奴隷にすることを決意した後、彼の主人となった。第7部隊長にふさわしい、気性が激しく、冷静で、真面目な女性である。他の部隊長たちよりも真剣にシュキと戦うことがよくある。彼女は' WHERE character_id = 'CH003916';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b170335-THTEXHKfMQwW.png', birthday = '8月28日', blood_type = 'A', voice_actor = '宮本侑芽', height = 159, description = '種族：人間・ピーチ　能力：「高潔な志」、「<i>「学習」</i>」　所属：対魔部隊（第7部隊副隊長）　家族： 東 戸部（祖母）、東 吹雪（母）、東 八千穂（姉）、東 マイア（姉）、東 ホマレ（義姉）、東 ユミナ（義姉）' WHERE character_id = 'CH003917';
