UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b170333-tX4fYxtmO7Hd.png', birthday = '6月30日', blood_type = NULL, voice_actor = '楠木ともり', height = NULL, description = '種族：ヒューマノイド・シュキ・ピーチ　能力：私はお姉さん、<i>「無敵」</I>　所属：隠れの里　和倉青羽は、和倉優希の姉であり、彼に「立派な若者」であるとはどういうことかを教えていたが、少なくとも6年前、マトー災害の際に失踪してしまった。' WHERE character_id = 'CH003920';
