UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b174190-Yl9xcIc5VTtI.jpg', birthday = '9月10日', blood_type = 'AB', voice_actor = '羊宮妃那', height = 171, description = '職業：中学生（2年生）　山田アンナは物語のヒロインであり、市川京太郎の同級生で、恋の相手でもある。見た目は可愛いが、実はおっちょこちょいで、見た目とは裏腹にとても子供っぽい一面もある。  彼女は雑誌のモデルや女優としても活躍している。男女問わず大人気だが、不器用な一面もある。アンナは図書館で頻繁におやつを食べており、京太郎を困らせている。また、京太郎が他の誰かと関わると、執着に近いほどの嫉妬を見せることもある。' WHERE character_id = 'CH003934';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b174191-ZxpNhPXKgxhX.jpg', birthday = '3月26日', blood_type = 'B', voice_actor = '堀江瞬', height = NULL, description = '職業：中学生（2年生） Twitter：https://twitter.com/thanatos_moros  市川は、物語『僕の心のヤバイ奴』の主人公であり、山田アンナの同級生である。 漫画の冒頭では、陰気で人付き合いが苦手、サディスティックな少年として描かれ、クラスメートを殺したいとさえ思っているが、実のところ彼は、自己評価が極端に低く、ただ自分のそばにいるだけで周囲の人々が嫌悪感を抱いていると信じ込んでしまうほどだが、唯一その人を' WHERE character_id = 'CH003935';
