UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b297346-JRFPFZaZxfzK.png', birthday = NULL, blood_type = NULL, voice_actor = '福島潤', height = NULL, description = NULL WHERE character_id = 'CH003938';
