UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329620-LcT59lPQzwum.png', birthday = NULL, blood_type = NULL, voice_actor = '松本大', height = NULL, description = NULL WHERE character_id = 'CH004163';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329629-aWURcDVlTNoQ.png', birthday = NULL, blood_type = NULL, voice_actor = '豊口めぐみ', height = NULL, description = NULL WHERE character_id = 'CH004164';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329655-AGaZInSXey4F.png', birthday = NULL, blood_type = NULL, voice_actor = '前野智昭', height = NULL, description = NULL WHERE character_id = 'CH004165';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323649-x8dZmPhNREKx.png', birthday = NULL, blood_type = NULL, voice_actor = '麦穂あんな', height = NULL, description = 'アダンドラは、ブラックパンサーに似た高ランクのモンスターである。その獰猛さは極めて激しく、森で遭遇すれば死を免れないと言われ、たった1体を倒すだけでも、高ランクの冒険者たちによる複数のパーティが力を合わせなければならないほどである。' WHERE character_id = 'CH004166';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323659-uABwn7l9th0i.png', birthday = NULL, blood_type = NULL, voice_actor = '杉田智和', height = NULL, description = '精鋭冒険者グループ「サンダーキング」のリーダー。冒険者の中でもトップクラスの存在であり、その実力は「モンスター殲滅隊」の隊長を務めるほどである。 頼りになる人物だが、仲間たちの前では時折、少しぼんやりとした一面を見せることもある。レベル2の「魔法耐性」スキルとレベル3の「ロングソード」スキルを持っている。アイビーには優しく接している。' WHERE character_id = 'CH004167';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329630-3R6SabmkDBRI.png', birthday = NULL, blood_type = NULL, voice_actor = '斎藤楓子', height = NULL, description = NULL WHERE character_id = 'CH004168';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329656-3HfJdjj1yjQy.png', birthday = NULL, blood_type = NULL, voice_actor = '浪川大輔', height = NULL, description = NULL WHERE character_id = 'CH004169';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323652-Y4FKwHpSDqk2.png', birthday = NULL, blood_type = NULL, voice_actor = '平野文', height = NULL, description = 'ラトミ村の占い師。「一ツ星」の予知能力を持つ。村にとって、特産品であるザロの最適な収穫時期を占う、かけがえのない存在である。' WHERE character_id = 'CH004170';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323660-wcseqZ3ljHwH.png', birthday = NULL, blood_type = NULL, voice_actor = '安元洋貴', height = NULL, description = '精鋭冒険者グループ「サンダー・キング」の一員。 かわいいものが好きで、特にソラに目をつけている。人の顔を覚えるのが得意だ。スキルには、徒手格闘（ランク2）、水魔法（ランク2）、片手剣（ランク2）がある。アイビーには優しく接している。' WHERE character_id = 'CH004171';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329631-8wTArte5FDPu.png', birthday = NULL, blood_type = NULL, voice_actor = '劉セイラ', height = NULL, description = NULL WHERE character_id = 'CH004172';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329639-sknhg3kFWxbK.png', birthday = NULL, blood_type = NULL, voice_actor = '中島ヨシキ', height = NULL, description = NULL WHERE character_id = 'CH004173';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329657-AJGmaqRRd2zZ.png', birthday = NULL, blood_type = NULL, voice_actor = '森川智之', height = NULL, description = NULL WHERE character_id = 'CH004174';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323653-Pwdfg4iSdpEJ.png', birthday = NULL, blood_type = NULL, voice_actor = '三宅健太', height = NULL, description = 'ラトメ村自警団の団長。彼と彼の部隊は、村の門の警備やパトロールなどの任務を交代で担当している。思いやりがあり、活発な性格で、自分が正しいと信じたことはすぐに実行に移す「行動派」である。 しかし、彼はつい熱中しすぎてしまい、時にはやりすぎてトラブルを引き起こすこともあるため、副隊長のヴェリヴェラから頻繁に注意を受けている。彼はアイビーに強く惹かれており、いつも彼女をじっと見つめている。' WHERE character_id = 'CH004175';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323661-ZRNx3m4XsSls.png', birthday = NULL, blood_type = NULL, voice_actor = '勝杏里', height = NULL, description = NULL WHERE character_id = 'CH004176';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329641-lMe9ubcXlIVq.png', birthday = NULL, blood_type = NULL, voice_actor = '高橋伸也', height = NULL, description = NULL WHERE character_id = 'CH004177';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329658-aa6k8ZGAh0AX.png', birthday = NULL, blood_type = NULL, voice_actor = '綿貫竜之介', height = NULL, description = NULL WHERE character_id = 'CH004178';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323654-cGgIKLUHobWv.png', birthday = NULL, blood_type = NULL, voice_actor = '鳥海浩輔', height = NULL, description = 'ラトメ村自警団の一員。副団長として、オグト団長を補佐している。衝動的なオグト団長の気まぐれに常に振り回される、苦労の絶えない男であり、団長をなだめたり、その残した後始末に追われたりして、いつも慌ただしく動き回っている。 普段は冷静だが、怒ると恐ろしいほどだと噂されている。実際、ヴェリヴェラが本気で激怒すると、オグト隊長でさえも怯えてしまうほどだ。彼はアイビーに優しく接している。' WHERE character_id = 'CH004179';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323662-lnNjPIu2WB1S.png', birthday = NULL, blood_type = NULL, voice_actor = '中井和哉', height = NULL, description = NULL WHERE character_id = 'CH004180';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329659-vmKCEzYHb4kR.png', birthday = NULL, blood_type = NULL, voice_actor = '木村隼人', height = NULL, description = NULL WHERE character_id = 'CH004181';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323655-vHZlnM7yjQNv.png', birthday = NULL, blood_type = NULL, voice_actor = 'てらそままさき', height = NULL, description = '精鋭冒険者グループ「炎の剣」のリーダー。威圧的な外見とは裏腹に、心根は優しい。手ごわい戦士であるだけでなく、鋭い知性も兼ね備えており、メンバーとの相互信頼のもとでグループを率いている。まさにその名にふさわしいリーダーである。 彼のスキルには、白兵戦（ランク3）、剣術（ランク2）、耐久力（ランク1）がある。彼はアイビーに優しく接している。' WHERE character_id = 'CH004182';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323663-R8pd9jlUf3Rb.png', birthday = NULL, blood_type = NULL, voice_actor = '井上麻里奈', height = NULL, description = '冒険者グループ「ヴェルダント・ウィンド」の一員。美しく、大人びた風貌の女性だが、少々不器用なところがある。2つ星のテイマーであり、ルスタルとリーデルという2体のレアなスライムを従えている。お菓子が大好きで、アイビーに優しく接している。' WHERE character_id = 'CH004183';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329660-1Ua8zwycTAxK.png', birthday = NULL, blood_type = NULL, voice_actor = '上田燿司', height = NULL, description = NULL WHERE character_id = 'CH004184';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323656-dRE7fvcaFHJ5.png', birthday = NULL, blood_type = NULL, voice_actor = '八代拓', height = NULL, description = '精鋭冒険者グループ「ソード・オブ・フレイム」の一員。陽気で人柄が良く、仲間、特に妹のように慕っているアイビーの世話をしっかりしてくれる。甘いものが大好きだ。 しかし、料理の腕は最悪で、食事当番が回ってくるたびに、彼自身も他のメンバーもがっかりさせられてしまう。3つ星の「炎の攻撃」スキルと、2つ星の「ロングソード」スキルを持っている。 アイビーには優しく接している。' WHERE character_id = 'CH004185';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323665-TgIBap4UqdEB.png', birthday = NULL, blood_type = NULL, voice_actor = '土岐隼一', height = NULL, description = '冒険者グループ「ヴェルダント・ウィンド」の一員。ミーラの兄であり、マルマの双子の兄弟で、顔立ち、声、性格が似ている。2つ星の「防御」スキルと1つ星の「ロングソード」スキルを持っている。お菓子が大好きだ。' WHERE character_id = 'CH004186';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b298248-P733qcY9hZSi.png', birthday = NULL, blood_type = NULL, voice_actor = '梶裕貴', height = NULL, description = '異世界からやってきた、無敵の剣の達人。剣術の腕前に加え、超人的な直感力を備えており、目の前に現れた敵を殺すための最善の方法を、一瞥するだけで見抜くことができる。' WHERE character_id = 'CH004187';
