UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b335184-adnGU9EsZtij.png', birthday = NULL, blood_type = NULL, voice_actor = '石見舞菜香', height = NULL, description = NULL WHERE character_id = 'CH004209';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b314498-MWFE7NRdzs3H.jpg', birthday = NULL, blood_type = NULL, voice_actor = '黒沢ともよ', height = NULL, description = 'ナオミは「真実局」のエージェントで、アンドロイドの活動を監視するのが仕事だ。一見気さくそうに見えるが、冷静かつ理性的である。' WHERE character_id = 'CH004210';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b314499-Gq27VSRdxyIi.jpg', birthday = NULL, blood_type = NULL, voice_actor = '宮本侑芽', height = NULL, description = '10歳のアンドロイドだが、外見は17歳に見える。実年齢のせいか、世間知らずなところがあり、人付き合いに苦労することもあるが、心は優しい。' WHERE character_id = 'CH004211';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321571-FVsy4t3fBzll.png', birthday = NULL, blood_type = NULL, voice_actor = '嶋村侑', height = NULL, description = 'サラは火星で有名な歌手です。' WHERE character_id = 'CH004212';
