UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358815-jrg0wZXHYLRw.png', birthday = NULL, blood_type = NULL, voice_actor = '小林都', height = NULL, description = NULL WHERE character_id = 'CH004215';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358823-KULcSNg7iJ8u.png', birthday = NULL, blood_type = NULL, voice_actor = '長谷川暖', height = NULL, description = NULL WHERE character_id = 'CH004216';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321569-MSuWbBBf01eP.png', birthday = NULL, blood_type = NULL, voice_actor = '武内駿輔', height = NULL, description = 'ジーンは真理省の次長である。彼はローゲの兄である。' WHERE character_id = 'CH004217';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323383-DqzOcrVjzgbz.png', birthday = NULL, blood_type = NULL, voice_actor = '下山吉光', height = NULL, description = 'Rogeを開発した著名な科学者。' WHERE character_id = 'CH004218';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358816-aJkpnduejAFm.png', birthday = NULL, blood_type = NULL, voice_actor = '武蔵真之介', height = NULL, description = NULL WHERE character_id = 'CH004219';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321568-ap8QkVayRx4B.png', birthday = NULL, blood_type = NULL, voice_actor = '興津和幸', height = NULL, description = 'エデンは、火星の戦争遺跡を調査している若い男性だ。彼はそれを「研究」だとしているが、遺跡から入手した品々を実際にどうしているのかは定かではない。彼はのんきで気さくな性格の持ち主だ。' WHERE character_id = 'CH004220';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323371-7oXQyPQmRYBu.png', birthday = NULL, blood_type = NULL, voice_actor = '家中宏', height = NULL, description = NULL WHERE character_id = 'CH004221';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323688-rlMGM3zlIR7E.png', birthday = NULL, blood_type = NULL, voice_actor = '青山穣', height = NULL, description = NULL WHERE character_id = 'CH004222';
