UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321574-QMGp2pTZAFzm.png', birthday = NULL, blood_type = NULL, voice_actor = '宮内敦士', height = NULL, description = NULL WHERE character_id = 'CH004225';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323372-kfDCGKJxGPN0.png', birthday = NULL, blood_type = NULL, voice_actor = '伊瀬茉莉也', height = NULL, description = 'オペラはパペッティアに仕えている。' WHERE character_id = 'CH004226';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324141-RmmkSUan06O6.png', birthday = NULL, blood_type = NULL, voice_actor = '越後屋コースケ', height = NULL, description = NULL WHERE character_id = 'CH004227';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358818-s7Vbt96duZZD.png', birthday = NULL, blood_type = NULL, voice_actor = '広瀬さや', height = NULL, description = NULL WHERE character_id = 'CH004228';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321570-u8XipL9vAHAU.png', birthday = NULL, blood_type = NULL, voice_actor = '吉野裕行', height = NULL, description = 'ジャロンは、人間社会を打倒することを目指す、ニアンが率いる組織「アルター」の一員である。彼は「不滅の九人」の一人でもある。  組織の信条よりも快楽主義と個人的な楽しみを優先するジャロンは、快楽を追い求める人物であり、黄色い剣闘士を模倣し、その姿に変身する能力を持っている。' WHERE character_id = 'CH004229';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323378-14t4KpbERj8U.png', birthday = NULL, blood_type = NULL, voice_actor = '津田美波', height = NULL, description = 'エイスはアリスの双子の兄です。彼は穏やかで内気な少年で、読書が好きです。' WHERE character_id = 'CH004230';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324138-i587GbzN2DbI.png', birthday = NULL, blood_type = NULL, voice_actor = '大南友希', height = NULL, description = NULL WHERE character_id = 'CH004231';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358819-AeA55KBmZT4e.png', birthday = NULL, blood_type = NULL, voice_actor = '福原かつみ', height = NULL, description = NULL WHERE character_id = 'CH004232';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321575-NrXYmst88Iz1.png', birthday = NULL, blood_type = NULL, voice_actor = '津田健次郎', height = NULL, description = 'アフダルは、「チューナー」として知られるニアンを専門とする医師だ。口が悪く、人付き合いが苦手な性格だが、確かな技術と強い責任感を持ち、ニアンたちから信頼を寄せられている。' WHERE character_id = 'CH004233';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323379-qk6FtQ0RxrIY.png', birthday = NULL, blood_type = NULL, voice_actor = '津田美波', height = NULL, description = 'アリスはエスの双子の妹だ。彼女は意志が強く、口が鋭い。臆病な弟を軽蔑の眼差しで見下してはいるものの、心の中では彼を気にかけている。' WHERE character_id = 'CH004234';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324139-GrKHtmK67mnQ.png', birthday = NULL, blood_type = NULL, voice_actor = '塙真奈美', height = NULL, description = NULL WHERE character_id = 'CH004235';
