UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358821-JYnzg2cztNha.png', birthday = NULL, blood_type = NULL, voice_actor = '深見梨加', height = NULL, description = NULL WHERE character_id = 'CH004242';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321573-ctGIcBL2KDOL.png', birthday = NULL, blood_type = NULL, voice_actor = '小林千晃', height = NULL, description = 'ノイド262は、ガーディアンシップ局に所属し、アッシュ・スタールと共に活動する調査官である。彼は非常に聡明で、任務の遂行においても極めて効率的だが、人間らしさのいくつかの側面については、まだ完全には理解しきれていない。' WHERE character_id = 'CH004243';
