UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b332241-liBtMZMBkpEZ.png', birthday = '9月17日', blood_type = NULL, voice_actor = '太田哲治', height = NULL, description = NULL WHERE character_id = 'CH004254';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321822-PkgmI0WyqHB6.png', birthday = NULL, blood_type = NULL, voice_actor = '葉山翔太', height = NULL, description = NULL WHERE character_id = 'CH004255';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321815-XyUSo1G3OLA0.png', birthday = '2月14日', blood_type = 'B', voice_actor = '永瀬アンナ', height = NULL, description = 'マホロは、アラジンが深く恋い焦がれている女子高生だ。彼女は神摩利人の妹であり、彼に完全に夢中になっており、彼を自分だけのものにしたいと願っている。 彼女はアラジンや彼の求愛など全く気にも留めておらず、しばしば彼を「変」だ、あるいは「気持ち悪い」と見なしている。彼をそばに置いておくのは、自分の望むことをさせるために彼を操るためだけである。 特に兄の前では、外見上は可愛らしく甘い態度を装う傾向があるものの、本気を出せば、より manipulative な一面を臆することなく見せる。' WHERE character_id = 'CH004256';
