UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321816-kZX2udhbWoKm.png', birthday = '11月2日', blood_type = 'A', voice_actor = '斉藤次郎', height = NULL, description = NULL WHERE character_id = 'CH004258';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321817-e5EbldE9aK4n.png', birthday = '5月10日', blood_type = 'A', voice_actor = '野津山幸宏', height = NULL, description = NULL WHERE character_id = 'CH004259';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324296-0Gc869J6JAI6.png', birthday = NULL, blood_type = NULL, voice_actor = 'ならはしみき', height = NULL, description = 'アラジンの母親。' WHERE character_id = 'CH004260';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321818-bLccRWx95nym.png', birthday = NULL, blood_type = NULL, voice_actor = '佐々木望', height = NULL, description = 'シグマスクワッドの現リーダー。信じられないほど強力なキックで知られ、道満拳一郎の宿敵である。右腕である大英王太とは親友同士であり、二人はホンキ市の中学校をすべて制覇したことから、「神王たち」という異名で呼ばれている。 また、彼には妹の神まほろがいる。' WHERE character_id = 'CH004261';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324297-RbkrVPbGPojY.png', birthday = NULL, blood_type = NULL, voice_actor = 'チョー ', height = NULL, description = '「ニャン・ナイナイト・ラブ」に頻繁に登場し、お決まりのギャグとして定着している中年のビジネスマン。彼はジャスミンと特別な関係にあり、毎回司会者に彼女と過ごす時間を許してくれるよう頼んでいる。' WHERE character_id = 'CH004262';
