UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b288296-3CzbVaqiOULL.jpg', birthday = NULL, blood_type = NULL, voice_actor = '福山潤', height = NULL, description = NULL WHERE character_id = 'CH004280';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', birthday = NULL, blood_type = NULL, voice_actor = '梶原岳人', height = NULL, description = NULL WHERE character_id = 'CH004281';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b148333-YXACZTG2SVs7.png', birthday = NULL, blood_type = NULL, voice_actor = '浅沼晋太郎', height = NULL, description = '地球を滅ぼそうとしている悪の組織のリーダー。しかし、休みの日には、食事から大好きな動物であるパンダを眺めることまで、地球ならではの楽しみを存分に満喫している。' WHERE character_id = 'CH004282';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323320-NQuoQ041cu4c.png', birthday = NULL, blood_type = NULL, voice_actor = '中村悠一', height = NULL, description = NULL WHERE character_id = 'CH004283';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323954-FwenR4AbuyCc.png', birthday = NULL, blood_type = NULL, voice_actor = '土岐隼一', height = NULL, description = NULL WHERE character_id = 'CH004284';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b213803-HPkAVyhTG6ZQ.png', birthday = NULL, blood_type = NULL, voice_actor = '石橋陽彩', height = NULL, description = 'レッドレンジャーは方向音痴として知られており、将軍を倒すという強い正義感を持っている。彼の任務は、将軍が調子の悪い日であるため、いつも停戦に終わってしまう。' WHERE character_id = 'CH004285';
