UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b320020-i3qIAE0rILZn.jpg', birthday = NULL, blood_type = NULL, voice_actor = '大橋彩香', height = NULL, description = NULL WHERE character_id = 'CH004307';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b320021-HDE90ZWV7nsg.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小倉唯', height = NULL, description = NULL WHERE character_id = 'CH004308';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b320022-cNiryZXVnthp.jpg', birthday = NULL, blood_type = NULL, voice_actor = '岡本信彦', height = NULL, description = NULL WHERE character_id = 'CH004309';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b151039-vt0PxphUMha7.jpg', birthday = '7月7日', blood_type = NULL, voice_actor = '伊藤静', height = NULL, description = '役職：大審問官（最高拷問官） 好物：日本酒、ワイン、イカの塩辛、アンチョビ、チョコレート。特技：神を交えた「拷問」、裁縫。  あるレストランで美味しい料理を前にした彼女の反応を目撃されたことをきっかけに、彼女はヘルホードへの加入を勧誘された。彼女は休暇のたびに必ず実家を訪れる。実家には妹とその夫が住んでいるため、トーチャーは彼らに「さっさと出て行って、私の昔の部屋を再利用しろ」と言い続けている。しかし、もし彼らが実際にそうしようものなら――' WHERE character_id = 'CH004310';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b151042-udKP4meFOB3q.jpg', birthday = '3月3日', blood_type = NULL, voice_actor = '白石晴香', height = NULL, description = '肩書き：王女、帝国軍第3軍団司令官　国王の長女であり、帝国軍第3軍団の司令官を務める。 第3軍団は平均的な実力と見なされているが、王女自身は一対一の戦闘であれば、第1軍団のトップクラスの兵士さえも凌駕すると言われる。妹がいる。   彼女の特技は剣術全般に加え、FPSゲームである。' WHERE character_id = 'CH004311';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b151040-9ACpVTM6afXF.png', birthday = '4月10日', blood_type = NULL, voice_actor = '小林親弘', height = NULL, description = '属性：伝説の聖剣　特殊能力：使い手の魔力と共鳴し、切れ味を向上させる。あらゆる種類の魔法を切り裂くことができる。選ばれし者だけが使用できる聖剣。 「三大聖剣」の中でも、近接戦闘に最も優れている。王女が捕らえられる前日、刃の部分が外され、修理に出されていた。現在の刃はあくまで一時的な代用品に過ぎない。' WHERE character_id = 'CH004312';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319575-sngezSmrEmWi.png', birthday = '10月4日', blood_type = NULL, voice_actor = '山根綺', height = NULL, description = '肩書き：トップクラスの戦士兼ハーム・マーシャル（上級拷問官） 好きなフード：流行りのフード、かわいいフード、焼き肉。 特技：猛獣を意のままに操ること。 水泳教室に通って泳ぎを習得し、現在は長距離泳に秀でている。戦闘以外にも、獣の力を駆使して荒れ地を耕して農地に変えたり、廃墟となった町を破壊して土地を解放したりすることができる。フォッドが神であれば、決して食べ残しはしない。' WHERE character_id = 'CH004313';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328206-elj2XxbglVn8.png', birthday = '1月30日', blood_type = NULL, voice_actor = '千本木彩花', height = NULL, description = '好きな食べ物：シーザーサラダとプロシュート。  武器職人兼見習い拷問師。聖剣「エクス」を「拷問」するために、わざわざ拷問師の免許を取得した。紛れもない腕前で武器を操り、エクスを執拗に苦しめている。プライベートでは拷問師と親しく、彼女を「～ちゃん」という親しみを込めた呼び方で呼んでいる。' WHERE character_id = 'CH004314';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319576-ZlPOsJ3WVUJL.png', birthday = '5月10日', blood_type = NULL, voice_actor = '中原麻衣', height = NULL, description = '職種：書店店員　好きな食べ物：チョコレートケーキ、ホイップクリームがたっぷり入ったものなら何でも、ラーメン、から揚げ。特技：片手で卵を割ること。腰を後ろに回すダンス。7の倍数を素早く計算できること。 鬼ごっこが得意。基本的には専業主婦だが、時折実家の本屋を手伝っている。風景写真の本やイラスト入りの百科事典が好き。' WHERE character_id = 'CH004315';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328216-bjk00C3sjiym.png', birthday = NULL, blood_type = NULL, voice_actor = '相川遥花', height = NULL, description = NULL WHERE character_id = 'CH004316';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b180528-xaB7r9Pxa877.jpg', birthday = '9月1日', blood_type = NULL, voice_actor = '富田美憂', height = NULL, description = '役職：ハーム・マーシャル（上級拷問官） 好きな食べ物：ローストビーフ、スコーン。 特技：名門ペシュッツ家の娘。何でも得意（自称）。小さなマスコットを作るニードルフェルトの達人（両親談）。  ヴァンパイア一族は古くから存在している。現在では直接血を吸うことはなく、代わりに鉄分を豊富に含む食べ物を栄養源としている。この一族は日光に弱い。もし長時間日光を浴びると、肌が赤くなり、炎症を起こす。' WHERE character_id = 'CH004317';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328207-a17lkB8yaQZS.png', birthday = NULL, blood_type = NULL, voice_actor = '朝日奈丸佳', height = NULL, description = NULL WHERE character_id = 'CH004318';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328217-txub4ol7kuue.png', birthday = NULL, blood_type = NULL, voice_actor = '杉山里穂', height = NULL, description = NULL WHERE character_id = 'CH004319';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b151044-Q3qfTnRWyYgV.png', birthday = '2月14日', blood_type = NULL, voice_actor = '玄田哲章', height = NULL, description = '好きな食べ物：ビール、梅酒、マヨネーズ、カレー。彼は最も強力で無敵の三つ目の怪物であり、すべての悪魔の頂点に立つ存在だ。 恐ろしくもカリスマ性あふれる存在感と威厳ある風貌を持つが、その正体は、一人娘の魔王（マオ）を溺愛する慈愛に満ちた父親である。また、声優を追いかけたり、日曜朝のテレビ番組を観たりするなど、オタク的な一面も持っている。' WHERE character_id = 'CH004320';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327264-iEfoQE8z5rDH.png', birthday = NULL, blood_type = NULL, voice_actor = '泊明日菜', height = NULL, description = '陰鬼の弟。' WHERE character_id = 'CH004321';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328208-nnYgkpXjiX0n.png', birthday = NULL, blood_type = NULL, voice_actor = '川口桜', height = NULL, description = NULL WHERE character_id = 'CH004322';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b151038-YdJuCGMIbsJn.png', birthday = '5月29日', blood_type = NULL, voice_actor = '日高里菜', height = NULL, description = '役職：超上級拷問見習い　好物：フライドポテト、チョコレートアイスクリーム、リンゴジュース。特技：けん玉。  地獄の王の唯一の娘。経験を積むために拷問見習いとして働いているが、その階級は「ハイパー・シニア見習い」であるため、大審問官よりも上位に位置している。給料は、母親と買い物に行く際にキャンディを1つ貰えること。' WHERE character_id = 'CH004323';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328189-GG4sUL2f0UyS.jpg', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = 'トルトゥーラの助手。' WHERE character_id = 'CH004324';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328209-ijPmDo1zvf0w.png', birthday = NULL, blood_type = NULL, voice_actor = '古賀明', height = NULL, description = NULL WHERE character_id = 'CH004325';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b161606-NcG5SWCwa9rr.png', birthday = '8月8日', blood_type = NULL, voice_actor = '茅野愛衣', height = NULL, description = '肩書き：4級戦士兼ジュニア拷問官　好物：まんじゅう、味噌汁、筑前煮。特技：旅行プランの立案、サウナ。ジャイアントが戦う姿や拷問を行う姿を目撃した者は誰もいない。彼女は浴室の維持管理や掃除が得意だ。 「旅行の計画に迷ったら、ジャイアントに相談しろ」というのは、ヘルホード内での格言となっている。' WHERE character_id = 'CH004326';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328190-d55VqSH05uLh.png', birthday = '8月22日', blood_type = NULL, voice_actor = '福島潤', height = NULL, description = '好きな食べ物：ステーキと寿司。魔王の優秀な側近。 噂によると、戦闘力において魔王軍で2番目に強いと言われている。もともとはパートタイムの清掃員として魔王軍に加わったが、人手不足のため様々な形で手助けをするようになり、やがて魔王の側近となった。' WHERE character_id = 'CH004327';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328201-1ISq0OZXElTO.png', birthday = '3月19日', blood_type = NULL, voice_actor = '大塚芳忠', height = NULL, description = '好きな食べ物：お菓子やスナック。彼は長年にわたり王国に奉仕し、数々の軍事的功績により勲章を授与された「名誉騎士」である。 引退後は執事として王国に仕え、王女を厳重に見守る任務を負っているが、彼女に対して少し甘いところがあり、授業の帰り道にこっそりお菓子を買ってあげたり、中華料理店に寄り道したりしている。' WHERE character_id = 'CH004328';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328210-BZPd9GufqGEg.png', birthday = NULL, blood_type = NULL, voice_actor = '中西正樹', height = NULL, description = NULL WHERE character_id = 'CH004329';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b151043-0UVegvyyjY5h.png', birthday = '12月26日', blood_type = NULL, voice_actor = '井上ほの花', height = NULL, description = '役職：リーテュメント（中級拷問官） 好きな食べ物：フガシ、おかし、ロブスター。 特技：戦略ゲーム、クレーンゲーム。 陽鬼の誘いでバスケットボール部に入部したが、初日で辞めてしまった。 両親とも共働きのため、家事は得意。2人の弟がいる。' WHERE character_id = 'CH004330';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328204-Md31U7qh0tlq.png', birthday = NULL, blood_type = NULL, voice_actor = '木野日菜', height = NULL, description = NULL WHERE character_id = 'CH004331';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b151041-hlOqTHlPAX70.png', birthday = '6月11日', blood_type = NULL, voice_actor = '永瀬アンナ', height = NULL, description = '役職：リーテュルメント（中級拷問官） 特技：反射神経を要するゲーム。一からポテトチップスを作る。学生時代、バスケットボール部で活躍していた。バレンタインデーには、最も人気のある男子たちよりも多くのチョコレートをもらっていた。シルバーのアクセサリーに興味があるが、買う余裕がない。' WHERE character_id = 'CH004332';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b328205-mjl3KRWEEFr9.png', birthday = NULL, blood_type = NULL, voice_actor = '小野大輔', height = NULL, description = NULL WHERE character_id = 'CH004333';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b211472-CjXtCjSbYi7d.png', birthday = '3月21日', blood_type = NULL, voice_actor = '小林千晃', height = 175, description = '安達清は30歳の童貞で、人に触れると相手の心を読める能力を持つようになった。文房具メーカー「豊川」で営業サポートスタッフとして働いている。' WHERE character_id = 'CH004334';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b211447-LSFMeiDJGwdu.png', birthday = '7月3日', blood_type = NULL, voice_actor = '鈴木崚汰', height = 183, description = '黒沢優一は、豊川社の営業部に勤務している。' WHERE character_id = 'CH004335';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327580-5X0No6g77Nqd.png', birthday = NULL, blood_type = NULL, voice_actor = '大地葉', height = NULL, description = '黒澤の姉。彼女は非常に意志が強く、自己中心的で、自立心も旺盛であり、姉という立場を利用して弟をこき使うことがよくある。男女問わず人気がある。' WHERE character_id = 'CH004336';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327595-PA6taxGzMjTS.png', birthday = NULL, blood_type = NULL, voice_actor = '渡部桃花', height = NULL, description = 'ツゲの猫。' WHERE character_id = 'CH004337';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b316988-2MIlcB3DO9FT.png', birthday = '4月1日', blood_type = NULL, voice_actor = '古川慎', height = NULL, description = NULL WHERE character_id = 'CH004338';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327581-zZwuSf1Jb6eg.png', birthday = NULL, blood_type = NULL, voice_actor = '安元洋貴', height = NULL, description = '豊川と黒澤の元指導者であり、営業部長。気さくな性格で、思いやりのある人柄であり、頼りになる先輩である。' WHERE character_id = 'CH004339';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b316989-58vr9GHd7M7s.png', birthday = '9月15日', blood_type = NULL, voice_actor = '佐藤元', height = NULL, description = NULL WHERE character_id = 'CH004340';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b322210-oCc32OqDNRa4.png', birthday = NULL, blood_type = NULL, voice_actor = '白井悠介', height = NULL, description = NULL WHERE character_id = 'CH004341';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b322211-3eCXCPY5BxGW.png', birthday = NULL, blood_type = NULL, voice_actor = '小清水亜美', height = NULL, description = NULL WHERE character_id = 'CH004342';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b27221-f7hhCDENtZFa.png', birthday = NULL, blood_type = NULL, voice_actor = '斉藤壮馬', height = NULL, description = NULL WHERE character_id = 'CH004343';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b27282-RB0heJ9eID6d.png', birthday = NULL, blood_type = NULL, voice_actor = '木村良平', height = NULL, description = '真介は、ジンカとタマに出会った当時、ただの放浪の浪人だった。彼は二人の能力に魅了され、彼らに付いていけるよう情報を提供した。' WHERE character_id = 'CH004344';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b27283-8WDUspf0Fq1f.png', birthday = NULL, blood_type = NULL, voice_actor = '高田憂希', height = NULL, description = '非常に野心的で、生意気な、数百年もの歳月を生き抜いた狐のカタワラ。彼女は人間の兄であるジンカと共に、悪事を働く人間やカタワラをこの世から一掃し、平和と慈愛を広めるために各地を旅している。' WHERE character_id = 'CH004345';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146191-1kybBWWOU7nV.png', birthday = NULL, blood_type = NULL, voice_actor = '七海ひろき', height = NULL, description = '千夜は、父の神雲と共に活動する悪魔ハンターである。千夜はダンガイシュによって実験の対象とされ、体内に1000体の悪魔を埋め込まれた。' WHERE character_id = 'CH004346';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146620-m5t9pY4zmTwB.jpg', birthday = NULL, blood_type = NULL, voice_actor = '高垣彩陽', height = NULL, description = '気まぐれな女神である彼女は、実は現存する中で最も古く、最も強力な土地の神の一人でもある。彼女は山を動かしたり、気まぐれに時空を歪めたりすることさえできる。彼女には「りんず」という名の巫女兼侍女がついている。' WHERE character_id = 'CH004347';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146813-iOmhenmHs89A.png', birthday = NULL, blood_type = NULL, voice_actor = '東地宏樹', height = NULL, description = 'ライドは、ダンガイシュに雇われて鬼を討つ浪人である。普段は鬼の肉を食べたり売ったりしているため、「鬼喰い」というあだ名で呼ばれている。ライドは、風を操ることができる「マケン」という名の刀と、「脇差」という名の短刀の二刀を操る。' WHERE character_id = 'CH004348';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146617-usBeStobwIpP.jpg', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = 'ムドは戦いが大好きなドラゴンです。' WHERE character_id = 'CH004349';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146618-CqMELss8ag06.jpg', birthday = NULL, blood_type = NULL, voice_actor = '豊崎愛生', height = NULL, description = '千夜と月湖に付き従う水の神。水の近くにいると、姿を変えたり、力を増したりすることができる。' WHERE character_id = 'CH004350';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327819-PPoNSjHm0gmo.png', birthday = NULL, blood_type = NULL, voice_actor = '佐藤利奈', height = NULL, description = NULL WHERE character_id = 'CH004351';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146282-PmouDSmeRjAx.jpg', birthday = NULL, blood_type = NULL, voice_actor = '稲田徹', height = NULL, description = '道錬はダンガイシュの一員であり、「フォー・ビースト」の将軍の一人である。彼は虎に変身することができる。' WHERE character_id = 'CH004352';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146192-HZId3lsW6q63.jpg', birthday = NULL, blood_type = NULL, voice_actor = '内田真礼', height = NULL, description = '千夜のパートナー。月湖は、千夜に深い想いを抱く、内気で控えめな少女だ。よく千夜を助けようとするが、かえってトラブルを招いてしまうことが多いと感じている。（出典：MAL）' WHERE character_id = 'CH004353';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146671-IbxMTsqAhQ4i.jpg', birthday = NULL, blood_type = NULL, voice_actor = '津田健次郎', height = NULL, description = '野禅はダンガイシュのリーダーである。商人の息子として生まれたものの、野禅は霊的な力に恵まれていた。旅の僧に目をつけられたことをきっかけに、ダンガイシュに加わった。' WHERE character_id = 'CH004354';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327805-lU7Xumxq0TZn.png', birthday = NULL, blood_type = NULL, voice_actor = '星野充昭', height = NULL, description = NULL WHERE character_id = 'CH004355';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327811-umfRAdARQLiU.png', birthday = NULL, blood_type = NULL, voice_actor = '石上静香', height = NULL, description = NULL WHERE character_id = 'CH004356';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146283-nWRnNeINdFkJ.png', birthday = NULL, blood_type = NULL, voice_actor = '乃村健次', height = NULL, description = '神雲はダンガイシュの一員であり、「フォー・ビースト」の将軍の一人である。彼は竜に変身することができる。' WHERE character_id = 'CH004357';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b35554-3lg1IVaaFkh7.png', birthday = NULL, blood_type = NULL, voice_actor = '黒沢ともよ', height = NULL, description = '融合した存在である彼女は、半分がシャクヤク（人間）、もう半分がカガン（カタワラ）である。灼岩は通常、人間の姿をしているが、意のままに手足を巨大な岩柱に変えることができる。   シャクヤクは、隠された力があることが判明するまで、家族と共に貧しい生活を送っていた田舎の少女だったが、その力を理由に両親によって僧院に売られてしまった。そこで人間とカタワラを融合させる実験の対象となり、ゴーレム型のカタワラであるカガンと融合させられた。 しかし、その過程で事態は制御不能に陥り、彼女は制御を失い、そして……' WHERE character_id = 'CH004358';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327817-fUG8HWCpT6if.png', birthday = NULL, blood_type = NULL, voice_actor = '斧アツシ', height = NULL, description = NULL WHERE character_id = 'CH004359';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146619-j7zVG9fkCf8B.jpg', birthday = NULL, blood_type = NULL, voice_actor = '鈴木愛奈', height = NULL, description = 'りんずは、山の女神の侍女であり弟子である。彼女はジンカに一目惚れし、プラトニックな恋心を抱いた。' WHERE character_id = 'CH004360';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327807-46pRMWUNWFxS.png', birthday = NULL, blood_type = NULL, voice_actor = '江頭宏哉', height = NULL, description = NULL WHERE character_id = 'CH004361';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146998-nQFKXp5445UM.png', birthday = NULL, blood_type = NULL, voice_actor = '宮城一貴', height = NULL, description = '烈深は狂気じみており、その状態を心から楽しんでいる。彼にとって、殺すことほど楽しいことはない。彼の体は呪いでできており、何でも吐き出せる袋を常に持ち歩いている。' WHERE character_id = 'CH004362';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b4834-N3Rgvc0ASR1d.jpg', birthday = '4月13日', blood_type = NULL, voice_actor = '神谷浩史', height = NULL, description = '友引高校2年4組の生徒であるアタルは、仏教暦で最も不吉な日に生まれたため、信じられないほどの不運に見舞われている。彼は非常に好色で、愚かで、怠け者だ。 ラムから逃げ出そうとしたり、他の女性に言い寄ったりすることも多いが、実は彼女に本気の想いを抱いている。アタルの人生の最大の目標は、エキゾチックで美しい女性たち（ラムや彼女の宇宙人の友人たちのほとんどを含む）に囲まれたハーレムの中心で暮らすことだ。彼のナンパ術は、見る者をゾッとさせるほどで……' WHERE character_id = 'CH004363';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b4835-Blt6iPoFEQnr.jpg', birthday = NULL, blood_type = NULL, voice_actor = '上坂すみれ', height = NULL, description = 'ラムは、空を飛んだり電気ショックを放ったりできる美しい鬼の宇宙人だ。彼女は絶大な人気を誇り、文末に「～ダッチャ」（大まかに言えば「そう？」や「わかる？」といった意味）を付けることで有名だ。 女子高生の制服を着ている時を除けば、普段はトラ柄のビキニとニーハイのゴーゴーブーツというセクシーな衣装を身にまとっている。概して神のような性格で、甘く無邪気だが、ラムは非常に短気な一面も持っている。 彼女の人生の夢は、「ダーリンとのスイートホーム」で暮らすことで、そこでは……' WHERE character_id = 'CH004364';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b4836-trBkldOOOaIx.jpg', birthday = '4月1日', blood_type = NULL, voice_actor = '宮野真守', height = NULL, description = '面堂終太郎は、莫大な富と独自の私兵部隊を擁する「門堂財閥」の跡取りである。彼は、まるで空飛ぶ邸宅のような巨大なヘリコプターで学校に通っている。終太郎は侍の刀を携えており、しばしばアタルにそれを振りかざそうとする（アタルは素手でそれを防ぐことに長けている）。 非常にハンサムだが、アタルと同じくらい愚かで好色家である（ただ、その手口ははるかに洗練されている）。彼は、膨大な門堂財閥の財産を継ぐ後継者としての役割を極めて真剣に受け止めている。門' WHERE character_id = 'CH004365';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b18381-HSb3d3a2GoZb.jpg', birthday = NULL, blood_type = NULL, voice_actor = '石上静香', height = NULL, description = 'ラムの幼なじみであり、銀河で最も忠実な友人。このキャラクターの名前は、知識・芸術・美を司る神道の女神「七福神の弁財天」に由来している。 この「弁天」は、プレートメイルのビキニを身にまとい、「ブッチ」なヘアスタイルを誇り、空飛ぶエイリアン・チョッパーで空を駆け巡り、港湾労働者さながらの悪態をつき、ハイテクなバゾカを携える「スペース・バイカー・チャック」だ。彼女は生意気で、頭が良くて、気さくな性格だ。 また、神がかったユーモアのセンスを持ち、それ以上に優れた……' WHERE character_id = 'CH004366';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/29395.jpg', birthday = NULL, blood_type = NULL, voice_actor = '戸田恵子', height = NULL, description = NULL WHERE character_id = 'CH004367';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b60833-rOmvVwYZj0BB.png', birthday = NULL, blood_type = NULL, voice_actor = '島﨑信長', height = NULL, description = '植物がすべて電気を導く人工のジャングルで育った、読み書きができず頭の鈍いジャングルの少年。メンド家に雇われている老いぼれの庭師である祖父を除けば、真吾が外界と接する主な手段はテレビだけだった。 電気の流れるジャングルで一生を過ごしてきた真吾は、電気の影響を受けず、それを力の源として活用できるよう適応している。' WHERE character_id = 'CH004368';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/60567.jpg', birthday = NULL, blood_type = NULL, voice_actor = '高橋李依', height = NULL, description = NULL WHERE character_id = 'CH004369';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b49969-dRvk1HL2Wtcr.png', birthday = NULL, blood_type = NULL, voice_actor = '櫻井孝宏', height = NULL, description = 'ツバメはサクラの婚約者である。彼は自らを、西洋の黒魔術を修めた熟練の魔術師だと自負しているが、その黒魔術の腕前はせいぜい「まあまあ」か、せいぜい「まったくの当たり外れ」といったところで、その力は主にモンスターや死者の霊を召喚することに限られている。' WHERE character_id = 'CH004370';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b342405-aVDBaNBUHf7f.png', birthday = NULL, blood_type = NULL, voice_actor = '福山潤', height = NULL, description = NULL WHERE character_id = 'CH004371';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b18380-4vCyCQmiemmN.jpg', birthday = NULL, blood_type = NULL, voice_actor = '花澤香菜', height = NULL, description = 'ラムの幼なじみ。一見、甘く愛らしい赤毛の少女に見えるが、実は暴力的な二重人格の持ち主である。彼女の特殊能力は、キスをすることで相手の口から生命力を吸い取る能力だ。この能力を逆方向に使うこともできる。 子供の頃、ランは、より無鉄砲で無責任なラムの悪ふざけのせいで、よく怪我をしたりトラブルに巻き込まれたりしていた。また、彼女はレイに恋をしているが、残念ながらレイは依然としてラムを愛している。こうした理由から、彼女は復讐を果たすために地球へとやって来た。' WHERE character_id = 'CH004372';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b12958-h1em8MP8cSLp.png', birthday = NULL, blood_type = NULL, voice_actor = '悠木碧', height = NULL, description = '皆から「テン」と呼ばれているジャリテンは、ラムのいとこだ。テンは生意気で口達者な宇宙人の幼児だ。すべての鬼と同じように、テンにも独自の力がある。彼は空を飛び、火を吐くことができる。 しかし、まだ経験の浅い子供であるため、飛ぶのはぎこちなく遅く、火を吐くのもいつもうまくいくとは限らない。テンは子供だが、その年齢相応の振る舞いは決してしない。おむつをしている身にしては、大人のような知性を備えており、それはかなり衝撃的だ。早熟であることの表れの一つとして、テンはただひたすらに' WHERE character_id = 'CH004373';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b54535-4BV0FYUrpimc.png', birthday = NULL, blood_type = NULL, voice_actor = '梶裕貴', height = NULL, description = NULL WHERE character_id = 'CH004374';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b216788-k2CIJmfmi0ii.png', birthday = NULL, blood_type = NULL, voice_actor = '高橋伸也', height = NULL, description = 'クスケはアタルとホクトの親友であり、3人はよく一緒に騒動を起こしている姿が見られる。彼には彼女（彼のために「シノビ・ノバデ」のふりをしてくれた）がおり、他の女の子たちからもバレンタインのチョコレートをもらっていることから、どうやら女の子たちには人気があるようだ。 面堂終太郎や他の男子生徒たちと同様、彼もラムに恋をしており、彼女の純潔を守るため、アタルとのキスを阻止しようと試みる。物語の後半では、彼とホクトは次第に' WHERE character_id = 'CH004375';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b336404-ZuAZvxBetL1f.png', birthday = NULL, blood_type = NULL, voice_actor = 'チョー ', height = NULL, description = 'ルパの曽祖父は、自身の先祖とラムの先祖を結婚させるという取り決めを結び、両家を結びつけた。' WHERE character_id = 'CH004376';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b18007-jyZwbvkEa5m1.jpg', birthday = NULL, blood_type = NULL, voice_actor = '早見沙織', height = NULL, description = 'おユキはネプチューンの女王である。このシリーズにおけるネプチューンは、男性のほとんどが仕事を探すために惑星外へ出ざるを得ないため、女性だけが暮らす凍てついた雪の惑星となっている。彼女は子供の頃、ラム、ラン、弁天と小学校の同級生だった頃、よく一緒に遊んでいた。 彼女は明らかに、日本の民話に登場する「雪女」をモデルにしています。そのため、氷や雪、そして極寒を操り、生み出す力を持っています。通常は長くて優雅な着物を身にまとい、おユキは物腰が柔らかく、気品に満ちており、' WHERE character_id = 'CH004377';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b19104-lUSvR3jbvRfZ.jpg', birthday = NULL, blood_type = NULL, voice_actor = '沢城みゆき', height = NULL, description = '日本語で「サクラ」は「桜」を意味します。彼女はかつて、さまざまな病に悩まされる病弱な少女でした。その多くは、彼女の体に憑依した精霊によるものでした。 叔父のチェリーの助言に従い、彼女はアタルを祓おうとしたが、その過程で、彼女に取り憑いていた悪霊たちが、不運な若者の体へと移ってしまった。彼女が二度目に彼を祓おうとしたとき、アタルに取り憑いていた悪霊の一体が、彼に彼女に飛びかかり、乳房を吸わせるように仕向けた。今では完全に健康を取り戻し、' WHERE character_id = 'CH004378';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b3646-FDsINzDkEul2.jpg', birthday = NULL, blood_type = NULL, voice_actor = '高垣彩陽', height = NULL, description = '友引高校2年4組に編入してきた転校生。彼女は女の子だが、父親が「浜茶屋の後継者は男でなければならない」と主張しているため、龍之介を男の子として育て、彼女自身も男だと主張している。 「浜茶屋」を経営するために、風変わりな父親に男の子として育てられたため、彼女の振る舞いは男の子そのもので、かなり荒っぽい。しかし、実際には女の子であるため、男の子のように扱われることを嫌っている。彼女は自分の女性的な一面を存分に発揮したいと切望しているが、父親がそれを邪魔してしまう。' WHERE character_id = 'CH004379';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b60829-Uv5n8tJPTCJG.png', birthday = NULL, blood_type = NULL, voice_actor = '村瀬歩', height = NULL, description = '竜之介と渚の結婚は、長年の友人である両家の父親たちによって取り決められた。 渚は龍之介に深く恋しているが、龍之介はそれを拒んでいる。当初は「他の女の子とは結婚できない」と主張していたが、やがて渚の激しいアプローチに嫌気がさしてしまったのだ。渚は大食漢であり、相撲のチャンピオンでもあり、その強さは龍之介さえも凌ぐほどである。' WHERE character_id = 'CH004380';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b22390-Fsmh9BTjISM1.jpg', birthday = NULL, blood_type = NULL, voice_actor = '佐藤せつじ', height = NULL, description = '「メガネ」というあだ名を持つストームトルーパーズのリーダーで、強い個性を持っており、主に（自分自身のためではあるが）ラムの注目を集めるべく、ストームトルーパーズの策略を指揮している。 普段はアタルに対して敵対的だが、暇な時にはよく彼とつるんでいる。哲学的な独り言や突拍子もない発言をしばしば口にし、ファシズムや共産主義に親和性があるようだ。' WHERE character_id = 'CH004381';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/17499.jpg', birthday = NULL, blood_type = NULL, voice_actor = '高木渉', height = NULL, description = 'サクラの放浪僧の叔父。チェリーの本名は「サクラんぼ」で、これは日本語で文字通り「さくら」を意味する。しかし、この言葉の漢字は「狂った僧」とも読めるため（これは彼を形容するのにまさにぴったりの表現だが）、彼は英語の呼び名で呼ばれることを好んでいる。 チェリーは驚くべき霊力を持っている（と本人は主張している）が、アタルに「ドム」が訪れることを予言することが多い（大した手柄ではないが）。彼はどこからともなく、しかもしばしば非常に奇妙な場所から現れる癖がある。その醜い顔と極めて小柄な体格は……' WHERE character_id = 'CH004382';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b49225-9LUk3C70IJfe.png', birthday = NULL, blood_type = NULL, voice_actor = '平野文', height = NULL, description = NULL WHERE character_id = 'CH004383';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/49957.jpg', birthday = NULL, blood_type = NULL, voice_actor = '千葉繁', height = NULL, description = '龍之介の父親は、おそらく史上最も嫌味で気難しい父親の一人だろう。彼の性格は、予測不能で気性が激しいと表現できる。 彼は「世の中は男が支配する」と考えており、そのため、娘には茶屋を経営する四代目藤波として十分な強さがないと信じ込んでいる。そのため、竜之介との関係は、父と娘というよりは、ボクシングのコーチと自慢の選手のような関係に近い。' WHERE character_id = 'CH004384';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/54541.jpg', birthday = NULL, blood_type = NULL, voice_actor = '三石琴乃', height = NULL, description = NULL WHERE character_id = 'CH004385';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b60287-jwkSqgJ4L7Ac.jpg', birthday = NULL, blood_type = NULL, voice_actor = '石見舞菜香', height = NULL, description = '病院の窓から毎日アタルを見守っている、愛らしい少女。やがて彼女は、アタルの軽快な物腰とエネルギッシュな性格に惹かれていく。死後、彼女の霊はサクラを訪ね、サクラは彼女が後悔なく成仏できるよう、望とアタルのデートを手配する。' WHERE character_id = 'CH004386';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/60275.jpg', birthday = NULL, blood_type = NULL, voice_actor = '関智一', height = NULL, description = '近隣のブツメツ高校の組長。シノブに一途な想いを抱いている。' WHERE character_id = 'CH004387';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b4837-MyjmNYCS21b0.jpg', birthday = NULL, blood_type = NULL, voice_actor = '内田真礼', height = NULL, description = 'アタルの幼なじみであり、同級生。ラムが現れるまでは、アタルの恋人でもあった。几帳面で清潔感があり、甘えん坊で小柄な若い女性で、典型的な「理想的な日本人女性」と言える。 ラムが現れて間もなく、シノブは超人的な力を身につけ始めた。彼女はクラスの女子全員と同様、メンドに片思いをしている。彼女はしばしば、アタル、ラム、シュタロウ、そして彼女自身からなる「4人組」の一員となっている。（出典：ウィキペディア）' WHERE character_id = 'CH004388';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/49951.jpg', birthday = NULL, blood_type = NULL, voice_actor = '古川登志夫', height = NULL, description = NULL WHERE character_id = 'CH004389';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b60055-yqPVN4gtbIsy.png', birthday = NULL, blood_type = NULL, voice_actor = '中村悠一', height = NULL, description = 'ルパは、完全な闇と巨大なキノコ、そして空飛ぶ豚が存在する世界の王子である。ルパの曽祖父の取り計らいにより、彼はラムと結婚することになっていた。ルパは彼女に会ったことはなかったが、それでも彼女と結婚するつもりだった。' WHERE character_id = 'CH004390';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/54543.jpg', birthday = NULL, blood_type = NULL, voice_actor = '桜井敏治', height = NULL, description = NULL WHERE character_id = 'CH004391';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b319083-G9RE8xgmMRcK.png', birthday = NULL, blood_type = NULL, voice_actor = 'くまいもとこ', height = NULL, description = 'コケルは、諸星あたるの将来の息子かもしれない少年である。（出典：うる星やつらWiki）' WHERE character_id = 'CH004392';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/n41582-XhtWKeVu9jnD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '釘宮理恵', height = NULL, description = 'この名もなき小さなキツネは、シリーズのファンからは一般的に「キツネ」と呼ばれている。彼は物語の序盤でシノブに恋をし、彼女に自分の存在を認めてもらいたいと切望しているが、その愛らしい振る舞いと子供っぽい純真さゆえに、シノブは彼の想いに全く気づいていない。    彼は都合の良い時に変身して他人に化ける力を持っている……しかし、身長や顔、声を変えることはできないため、どんなに努力しても誰をも騙すことは決してできない。' WHERE character_id = 'CH004393';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b18008-Xtw2VVOj8AE7.png', birthday = NULL, blood_type = NULL, voice_actor = '井上麻里奈', height = NULL, description = '修太郎の妹である涼子は、甘やかされて育った少女で、兄を狂わせようと、入念な計画を練り、それを実行することだけが唯一の楽しみであるようだ。  wikipedia' WHERE character_id = 'CH004394';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b49971-fKQAMC8lZMFZ.png', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = NULL WHERE character_id = 'CH004395';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b60057-NjDOt5DPqyPi.png', birthday = NULL, blood_type = NULL, voice_actor = '水瀬いのり', height = NULL, description = 'カルラは子供の頃からずっとルパを愛していた。ある日、ルパが婚約者であるラムの写真をカルラに見せたとき、カルラは幼なじみから凶暴な加害者へと一変した。それ以来、彼女は嫉妬のあまり、絶えずルパを脅し、恐怖に陥れ続けた。' WHERE character_id = 'CH004396';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b18379-DTJKhBXtP8j0.png', birthday = NULL, blood_type = NULL, voice_actor = '水樹奈々', height = NULL, description = '「カラス姫」。カラス天狗という異星種族に属する人型女性で、キスによって眠りから目覚めさせた男性と結ばれる運命にある。彼女にとって不運なことに、その相手はアタルだった。 彼と寝る気は全くないものの、種族のため、彼女はラムとシノブの両方を退けつつ、この変態の好色漢を、自分の子供をもうけるにふさわしい男に変えようと、あらゆる手段を講じる。どうやら彼女の父親は、源義経の一人だったらしい。' WHERE character_id = 'CH004397';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b60831-mRSEqHBg9lEo.png', birthday = NULL, blood_type = NULL, voice_actor = '坂口候一', height = NULL, description = 'ウニを世界的な珍味にしようと決意を固めた、同じくビーチ愛好家の一人。海産物へのその献身的な姿勢が、結局は彼自身とナギサの両方の命を奪うことになってしまう。' WHERE character_id = 'CH004398';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b29390-WpeX8CzzJ6Ui.png', birthday = NULL, blood_type = NULL, voice_actor = '三宅健太', height = NULL, description = 'アタルが教える教師の一人。  物憂げな中年の男性で、友引高校で教えることだけが唯一の楽しみだが、授業中に絶え間なく割り込まれるため、ラムやテン、あるいはシノブによって教室そのものが破壊されない限り、授業はうまくいかない。彼の名前は「温泉の印」を意味しており、普段は温泉の柄が入ったシャツを着ている。' WHERE character_id = 'CH004399';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b11156-u47Do4hx2DMb.png', birthday = NULL, blood_type = NULL, voice_actor = '入野自由', height = NULL, description = 'An employee at the Fate Production Bureau (運命製造管理局, Unmei Seizou Kanrikyoku) which makes doorknobs to the Dream Realm. He wears a rabbit costume which allows him to travel feely to and from subspace. Debuting late in the series (Vol. 31), he still plays in important role. He ends up falling in love with Shinobu after she finds him passed out and hungry in the street and gives him some food. Eventually he and Shinobu become a couple.  (Source: Wikipedia)' WHERE character_id = 'CH004400';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/60563.jpg', birthday = NULL, blood_type = NULL, voice_actor = '久野美咲', height = NULL, description = NULL WHERE character_id = 'CH004401';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b49963-Z3plWRDNUNUZ.png', birthday = NULL, blood_type = NULL, voice_actor = '井上和彦', height = NULL, description = NULL WHERE character_id = 'CH004402';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/n18378-M4M7arzSXRY5.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小西克幸', height = NULL, description = 'レイはとてもハンサムな鬼ですが、残念ながら主に食べることにしか興味がありません。彼は「ウシトラ」と呼ばれる、虎と牛を掛け合わせたような巨大な生き物に変身する能力を持っています。レイはまだ日本語を完全に習得していないため、一度に1～5語しか話せません。 若い頃、ランとラムは二人とも彼に恋をしていたが、彼はラムと婚約し、ランの心を傷つけ、ランはラムを憎むようになった。ラムは最終的に彼と別れたが、彼は彼女を追いかけるために地球へやって来た。' WHERE character_id = 'CH004403';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/49959.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小山力也', height = NULL, description = NULL WHERE character_id = 'CH004404';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b54539-u6rp0yO1AP9B.jpg', birthday = NULL, blood_type = NULL, voice_actor = '市道真央', height = NULL, description = 'トビマロの妹で、男性に対して極度の恐怖症を抱いている。' WHERE character_id = 'CH004405';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/60557.jpg', birthday = NULL, blood_type = NULL, voice_actor = '森永千才', height = NULL, description = NULL WHERE character_id = 'CH004406';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b49223-GX4Th4Mvvpz7.jpg', birthday = NULL, blood_type = NULL, voice_actor = '井上喜久子', height = NULL, description = '母親は昔気質で、現代の便利なものは一切使おうとしない。涼子は、その慎み深さや非の打ちどころのないマナー、そして古いものを大切にする姿勢を、母親から受け継いでいるようだ。' WHERE character_id = 'CH004407';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/60483.jpg', birthday = NULL, blood_type = NULL, voice_actor = '福西勝也', height = NULL, description = NULL WHERE character_id = 'CH004408';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313979-wlTwDgK9TlT5.png', birthday = '4月15日', blood_type = NULL, voice_actor = '川井田夏海', height = NULL, description = 'ある遺言により、モモチ・ホースを相続した16歳の孤児。正当な所有者として、彼女はホースから存在を追い出す能力を持っている。' WHERE character_id = 'CH004409';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313980-2JtFSglsp3B8.png', birthday = '5月9日', blood_type = NULL, voice_actor = '大塚剛央', height = NULL, description = '葵が7歳のとき、百道法師に迷い込み、「お守り様」に選ばれた。彼は任務を遂行するために鵺に変身するが、この役割は本来、ヒマリが担うべきものだったようだ。 ヌエに変身すると、彼は猫の耳、鳥の翼、狐の尾を持つ妖怪となる。お守り様として、ヌエは百道保生を守り、霊界から侵入してくる妖怪を退治する。' WHERE character_id = 'CH004410';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313981-a4i0HMM9LT1x.png', birthday = NULL, blood_type = NULL, voice_actor = '立花慎之介', height = NULL, description = 'お守り様の式神の一体。水蛇の姿をしている。' WHERE character_id = 'CH004411';
