UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323745-8Qd9HAFTvIhH.png', birthday = NULL, blood_type = NULL, voice_actor = '市川蒼', height = NULL, description = '百木保生に棲む、下級の妖怪の一体。' WHERE character_id = 'CH004413';
